def getSubstring(text, prefixString, suffixString):
    def head_score(sub):     # sub 的开头与 prefixString 的结尾最长重合多少
        for k in range(min(len(sub), len(prefixString)), 0, -1):
            if sub[:k] == prefixString[-k:]:
                return k
        return 0

    def tail_score(sub):     # sub 的结尾与 suffixString 的开头最长重合多少
        for k in range(min(len(sub), len(suffixString)), 0, -1):
            if sub[-k:] == suffixString[:k]:
                return k
        return 0

    best_score, best = -1, ""
    n = len(text)
    for l in range(n):
        for r in range(l + 1, n + 1):
            sub = text[l:r]
            score = head_score(sub) + tail_score(sub)
            if score > best_score or (score == best_score and sub < best):
                best_score, best = score, sub
    # ponytail: O(n^2 * L) 的直接枚举，长文本需要先用 KMP/Z 函数预处理每个起点、终点的匹配长度
    return best
